for(const q of BANK){const shift=[...q.id].reduce((n,c)=>n+c.charCodeAt(0),0)%q.options.length;const original=q.options[q.answer];q.options=q.options.slice(shift).concat(q.options.slice(0,shift));q.answer=q.options.indexOf(original);if(q.part===1)q.audio=q.options.map((s,j)=>`${'ABCD'[j]}. ${s}`).join(' ');if(q.part===2){const stem=responses[Number(q.group.replace('response',''))][0];q.audio=stem+' '+q.options.map((s,j)=>`${'ABC'[j]}. ${s}`).join(' ');}}
